package io.forgeloop.control.application; public record FeatureSubmission(String repository,String sourceRef,String title,String specification,double budgetUsd){ public FeatureSubmission {if(repository==null||!repository.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"))throw new IllegalArgumentException("Repository must be owner/name");if(sourceRef==null||sourceRef.isBlank()||title==null||title.isBlank()||specification==null||specification.isBlank())throw new IllegalArgumentException("Source, title, and specification are required");if(budgetUsd<=0||budgetUsd>500)throw new IllegalArgumentException("Budget must be between 0 and 500 USD");} }
